class Circle
  def draw(canvas) = canvas.circle(self)
end
class LegacyWidget
  def draw(canvas) = canvas.rect(x, y, w, h)
end

def render(items, canvas)
  items.each { |item| item.draw(canvas) }   # any object answering #draw
end
LegacyWidget.new.respond_to?(:draw)         # capability check, not a type check
